/* Calls the Macintosh SE ROM does not implement are declared with this, so using one
 * is a compile-time error that names the reason. Define SEROM_ALLOW_UNAVAILABLE
 * when running under a System file that adds them. */
#if defined(SEROM_ALLOW_UNAVAILABLE)
#define SEROM_UNAVAILABLE(msg)
#else
#define SEROM_UNAVAILABLE(msg) __attribute__((unavailable(msg)))
#endif
